    "Counted over your {count} most recent posts, which is as far back as this page goes." : "Geteld over je meest recente berichten in {count}, wat zo ver teruggaat als deze pagina.",
    "_Counted over your one post._::_Counted over all {count} of your posts._" : ["Geteld over je ene bericht heen.", "Geteld over al je berichten in {count}."],
    "Could not work out your statistics." : "Kan uw statistieken niet achterhalen.",
    "new" : "nieuw",
    "_%n engagement in {month}_::_%n engagement in {month}_" : ["%n betrokkenheid bij {month}", "%n betrokkenheid bij {month}"],
    "_%n follower in {month}_::_%n followers in {month}_" : ["%n volger in {month}", "%n volgers in {month}"],
